contract InvMutTest is Test {
    Reentrancy_bonus c;
    function setUp() public { c = new Reentrancy_bonus(); }
    function testFuzz_property(address recipient) public {
        vm.assume(recipient != address(0));
        vm.assume(recipient != address(c));

        vm.deal(address(c), 1000 ether);

        vm.prank(recipient);
        try c.getFirstWithdrawalBonus(recipient) {
        } catch {}

        assertTrue(!c._locked());
    }
}
